using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using ModelContextProtocol;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddHttpClient("WeatherApi", client =>
{
    client.BaseAddress = new Uri("https://api.weather.example.com/");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool, Description("Gets the current weather forecast for a given city.")]
    public static async Task<string> GetForecast(
        IHttpClientFactory httpClientFactory,
        [Description("The city name to look up weather for")] string city,
        [Description("Temperature unit: 'celsius' or 'fahrenheit'")] string unit = "celsius")
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");
        var response = await client.GetAsync($"forecast?city={Uri.EscapeDataString(city)}&unit={unit}");
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync();
    }

    [McpServerTool, Description("Gets historical weather data for a city on a specific date.")]
    public static async Task<string> GetHistoricalWeather(
        IHttpClientFactory httpClientFactory,
        [Description("The city name")] string city,
        [Description("Date in YYYY-MM-DD format")] string date)
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");
        var response = await client.GetAsync($"history?city={Uri.EscapeDataString(city)}&date={date}");
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync();
    }
}

